-- Ultima fecha local: lunes - El_Rayo, 2026-10-26 21:00, 16 convocados.
-- Importar en la base existente de Goodfellas con el codigo actualizado.
-- Usa los mismos IDs de jugadores y cancha que la base local.
-- No modifica fechas existentes ni agrega jugadores al padron.
SET NAMES utf8mb4;
START TRANSACTION;
SET @gf_fecha_existente := (SELECT id FROM matches WHERE match_date = '2026-10-26 21:00:00' AND title = 'lunes - El_Rayo' LIMIT 1);
SET @gf_fecha_id := IF(@gf_fecha_existente IS NULL, LAST_INSERT_ID(), @gf_fecha_existente);
COMMIT;
SELECT @gf_fecha_id AS fecha_id, IF(@gf_fecha_existente IS NULL, 'Fecha agregada con 16 convocados', 'La fecha ya existia: no se modifico') AS resultado;
